 "deus:jergal": {
  "chave": "deus:jergal",
  "tipo": "deus",
  "fonte": "SCAG",
  "grupo": "faerunian",
  "nomeEn": "Jergal",
  "nome": "Jergal",
  "resumo": "Jergal é o velho e frio escriba dos mortos, lembrado sobretudo em enterros, quando alguém precisa registrar quem partiu.",
  "fatos": [
   {
    "cd": 10,
    "texto": "Deus indiferente que anota cada morte e guarda os registros dos falecidos. Seu símbolo é uma caveira mordendo um pergaminho, e seu nome costuma surgir em funerais."
   },
   {
    "cd": 10,
    "texto": "Onde as covas não têm nome, há quem escreva o nome do morto num pergaminho e o ponha na boca do cadáver, costume ligado a Jergal."
   },
   {
    "cd": 15,
    "texto": "Seus poucos sacerdotes trabalham como coveiros e zeladores de cemitérios. Não há templos próprios dele; seus fiéis são bem recebidos nas casas de Kelemvor, Deneir e até Myrkul."
   },
   {
    "cd": 20,
    "texto": "Diz-se que ajuda Kelemvor a mandar cada alma ao pós-vida certo. Todo ano, seus devotos enviam a locais sagrados os registros das mortes que anotaram."
   },
   {
    "cd": 20,
    "texto": "Na era de Netheril, era o terrível senhor da morte, do assassinato e da discórdia. Ruínas abandonadas desse culto antigo e sombrio ainda podem existir."
   },
   {
    "cd": 25,
    "texto": "Cansado do poder, cedeu seu trono de ossos a Bane, Bhaal e Myrkul, que repartiram seus domínios num jogo de ossinhos feitos dos dedos dele. Jergal saiu sorrindo, aliviado do fardo."
   }
  ],
  "palavras": [
   "jergal",
   "escriba",
   "mortos",
   "funeral",
   "caveira",
   "pergaminho",
   "coveiro",
   "cemiterio"
  ]
 },
