  "resumo": "Deus anão dos viajantes e das tempestades, a quem os anões que vivem longe de casa pedem proteção na estrada.",
  "fatos": [
   {
    "cd": 10,
    "texto": "É o deus anão dos que andam por terras distantes e enfrentam o mau tempo; caravaneiros e andarilhos anões costumam murmurar seu nome antes de partir."
   },
   {
    "cd": 15,
    "texto": "Seu símbolo é uma maça segura por manoplas. Anões que vivem fora dos clãs, em cidades humanas, muitas vezes o têm como protetor."
   },
   {
    "cd": 20,
    "texto": "Faz parte dos Mordinsamman, os deuses anões aliados de Moradin. Rege tempestades e viagens, e seus clérigos invocam trovões e ventos contra quem ameaça os viajantes."
   },
   {
    "cd": 25,
    "texto": "Diz-se que ele próprio é um errante que abençoa quem mantém laços com o lar mesmo de longe; seus devotos acolhem anões perdidos e os ajudam a voltar ao seu povo."
   }
  ],
