  "nome": "Tarsellis Meunniduin",
  "resumo": "Um deus élfico pouco lembrado, senhor das montanhas, dos rios e dos lugares selvagens.",
  "fatos": [
   {
    "cd": 10,
    "texto": "É um dos deuses dos elfos, ligado às montanhas, aos rios e às terras sem dono. Viajantes élficos às vezes murmuram seu nome antes de cruzar um desfiladeiro ou um vau."
   },
   {
    "cd": 15,
    "texto": "Seu símbolo é uma montanha com um rio descendo por ela. Elfos que vivem nas alturas ou guiam caravanas por trilhas de serra costumam levá-lo gravado em pingentes."
   },
   {
    "cd": 20,
    "texto": "Faz parte da Seldarine, a corte de deuses élficos de Arvandor. Tem temperamento livre e imprevisível, como o tempo nas montanhas, e não gosta de ser preso a regras."
   },
   {
    "cd": 20,
    "texto": "Seus sacerdotes servem tanto à natureza quanto à tempestade: protegem nascentes e picos e são capazes de chamar ventos e trovões contra quem profana os lugares selvagens."
   },
   {
    "cd": 25,
    "texto": "Quase não tem templos; seus fiéis rezam em cumes e cachoeiras. Dizem que quem suja uma nascente sagrada dele encontra a trilha de volta tomada por avalanches e enchentes."
   }
  ],
