 "deus:tempus": {
  "chave": "deus:tempus",
  "tipo": "deus",
  "fonte": "SCAG",
  "grupo": "faerunian",
  "nomeEn": "Tempus",
  "nome": "Tempus",
  "resumo": "Tempus é o deus da guerra, o Martelo dos Inimigos, cujo nome todo soldado invoca antes de uma batalha.",
  "fatos": [
   {
    "cd": 10,
    "texto": "Rege a guerra e a coragem em combate. Seu símbolo é uma espada em chamas apontada para cima, e soldados e mercenários de toda parte o invocam."
   },
   {
    "cd": 10,
    "texto": "Não tem lado fixo: pode favorecer um exército hoje e abandoná-lo amanhã. Ninguém deve contar com sua bênção como coisa garantida."
   },
   {
    "cd": 15,
    "texto": "Seus sacerdotes costumam marchar junto das tropas e companhias mercenárias, lutando na linha e animando os companheiros. São bons estrategistas e respeitam quem luta com bravura."
   },
   {
    "cd": 20,
    "texto": "Os fiéis seguem a Honra de Tempus: dar arma a quem precisa, nunca desprezar o adversário, treinar todos para lutar e evitar rixas pessoais. Torturar, matar quem não luta ou envenenar poços e plantações é pecado grave."
   },
   {
    "cd": 20,
    "texto": "Para a igreja, a guerra é uma força natural, como uma tempestade que toda civilização provoca; não deve ser temida, pois nela qualquer um pode morrer ou se tornar líder."
   },
   {
    "cd": 25,
    "texto": "Dizem que ele aparece antes das batalhas como um guerreiro vestido à moda de quem o vê. Montando a égua branca Veiros, anuncia vitória; no garanhão negro Deiros, derrota; com um pé em cada, incerteza."
   }
  ],
  "palavras": [
   "tempus",
   "guerra",
   "martelo dos inimigos",
   "senhor das batalhas",
   "espada flamejante",
   "soldado",
   "batalha",
   "mercenario"
  ]
 },
