 "deus:thardHarr": {
  "chave": "deus:thardHarr",
  "tipo": "deus",
  "fonte": "MTF",
  "grupo": "dwarven",
  "nomeEn": "Thard Harr",
  "nome": "Thard Harr",
  "resumo": "Thard Harr é o deus anão das selvas e da caça, venerado pelos anões selvagens que vivem longe das fortalezas de pedra.",
  "fatos": [
   {
    "cd": 10,
    "texto": "É um deus dos anões, mas não das minas: rege a natureza bravia e a caçada. Quem o invoca costuma viver em matas densas, longe de salões e forjas."
   },
   {
    "cd": 15,
    "texto": "Seu símbolo são duas manoplas com garras. Os fiéis lutam de perto, com fúria, e muitos usam luvas ou braceletes com lâminas em sua honra."
   },
   {
    "cd": 15,
    "texto": "Seus devotos são sobretudo anões selvagens das selvas do sul. Desconfiam de estranhos que derrubam árvores ou caçam por esporte, e respeitam quem caça só o necessário."
   },
   {
    "cd": 20,
    "texto": "Faz parte dos Mordinsamman, o panteão anão encabeçado por Moradin. É bondoso, mas indomável, e seus druidas e caçadores preferem a liberdade da mata a qualquer lei de clã."
   },
   {
    "cd": 25,
    "texto": "Os anões das fortalezas o veem quase como um parente excêntrico. Seus fiéis acreditam que a força vem de viver como fera entre feras, e honram a presa abatida antes de comê-la."
   }
  ],
  "palavras": [
   "thard harr",
   "caca",
   "selva",
   "manoplas",
   "garras",
   "anao selvagem",
   "natureza"
  ]
 },
